+      b.addEventListener('click', function () {
+        activate(b.getAttribute('data-tab'));
+      });
+    });
+
+    var first = buttons[0];
+    if (first) activate(first.getAttribute('data-tab'));
+  }
+
+  function initCarousel(root) {
